INSERT INTO `discussions` VALUES (1,15,9,'Enim libero exercitationem libero voluptatem sed incidunt cupiditate vero.','Nihil laudantium consequatur aut nulla. Aut expedita quia ut aspernatur autem consectetur vero. Architecto molestias voluptatem voluptatem numquam dignissimos voluptas minima. Quis quisquam optio omnis nam.',0,'2026-07-21 16:50:25','2026-07-21 16:50:25'),(2,25,8,'Aspernatur repellat enim sed illo officia natus corrupti.','Earum eligendi illo voluptatem nisi voluptatem optio dicta. Dolorem voluptas iure qui eius similique dolores. Reprehenderit facilis harum et distinctio qui repudiandae aut qui.',0,'2026-07-21 16:50:25','2026-07-21 16:50:25'),(3,26,6,'Iure qui aut non sed aut autem.','Praesentium omnis praesentium blanditiis reprehenderit sequi doloremque. Repudiandae quia ex eum. Aut aut quibusdam non aut numquam.',0,'2026-07-21 16:50:25','2026-07-21 16:50:25'),(4,62,3,'Deserunt enim id dolor corrupti voluptatem tenetur.','Rerum molestiae nesciunt sequi iusto qui animi. Excepturi eligendi quos esse aut. Molestias mollitia iste qui sit ipsa fugiat fuga.',0,'2026-07-21 16:50:25','2026-07-21 16:50:25'),(5,70,4,'Optio enim vero quos odit in neque quia.','Ut in delectus sed fuga esse et sint quaerat. Enim non est nostrum amet eos et. Soluta repellendus labore libero dolorem. Possimus voluptatem inventore facilis corporis nam.',0,'2026-07-21 16:50:25','2026-07-21 16:50:25');
