--
-- Table structure for table `exam_questions`
--

DROP TABLE IF EXISTS `exam_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `exam_questions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `type` enum('multiple_choice','essay') NOT NULL,
  `question` text NOT NULL,
  `option_a` varchar(191) DEFAULT NULL,
  `option_b` varchar(191) DEFAULT NULL,
  `option_c` varchar(191) DEFAULT NULL,
  `option_d` varchar(191) DEFAULT NULL,
  `option_e` varchar(191) DEFAULT NULL,
  `correct_option` varchar(1) DEFAULT NULL,
  `score` smallint(5) unsigned NOT NULL DEFAULT 10,
  `order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_questions_exam_id_index` (`exam_id`),
  CONSTRAINT `exam_questions_exam_id_foreign` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

